/// <summary>
/// PricingAttribute of table <c>InventDim</c> field SHA1HashHex.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesLine, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeInventDimSHA1HashHex extends GUPPricingAttributeInventDim implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, SHA1HashHex);
}

    public Set getAllowedValues()
    {
        var       ret = new Set(Types::String);
        InventDim inventDim;

        while select inventDim
            group by SHA1HashHex
        {
            if (! ret.in(inventDim.SHA1HashHex))
            {
                ret.add(inventDim.SHA1HashHex);
            }
        }
        return ret;
    }

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(InventDim, SHA1HashHex));
        qbr.value(queryValue(_value));
    }
